async function installed(name,from){
  for(let directory=from;;directory=dirname(directory)){
    const candidate=join(directory,'node_modules',name,'package.json');
    try{await access(candidate);return realpath(dirname(candidate));}catch{}
    if(dirname(directory)===directory)return null;
  }
}
function isNotice(name){return /^(?:licen[cs]e|copying|copyright|notice)(?:[._-].*)?$|^third[-_ ]?party[-_ ]?notices?(?:[._-].*)?$/i.test(name)&&! /\.(?:[cm]?js|tsx?|json|map)$/i.test(name);}
async function notices(directory,base=directory,depth=0){
  const result=[];
  for(const entry of await readdir(directory,{withFileTypes:true})){
    if(entry.isDirectory()&&depth<5&&!['node_modules','.git'].includes(entry.name))result.push(...await notices(join(directory,entry.name),base,depth+1));
    else if(entry.isFile()&&isNotice(entry.name)){
      const path=join(directory,entry.name),buffer=await readFile(path);
      if(!buffer.includes(0))result.push({path:relative(base,path).replaceAll('\\','/'),text:buffer.toString('utf8').trim()});
    }
  }
  return result.sort((a,b)=>a.path.localeCompare(b.path));
}
async function collect(directory){
  directory=await realpath(directory);if(visited.has(directory))return;visited.add(directory);
  const manifest=JSON.parse(await readFile(join(directory,'package.json'),'utf8'));
  if(!manifest.name?.startsWith('@wangxu/')){
    const files=await notices(directory);
    const key=`${manifest.name}@${manifest.version}`;
    const cached=UPSTREAM_NOTICES[key]??(manifest.name.startsWith('@msgpackr-extract/msgpackr-extract-')&&manifest.version==='3.0.4'?UPSTREAM_NOTICES['@msgpackr-extract/msgpackr-extract-darwin-arm64@3.0.4']:undefined);
    if(!files.length&&cached){
      if(createHash('sha256').update(cached.text).digest('hex')!==cached.sha256)throw new Error(`Cached notice integrity failed for ${key}`);
      files.push({path:'UPSTREAM-LICENSE',text:`Source: ${cached.url}\nSHA256: ${cached.sha256}${cached.note?`\nProvenance: ${cached.note}`:''}\n\n${cached.text}`});
    }
    if(key==='@bufbuild/protobuf@1.10.1'){
      for(const file of ['dist/esm/binary-encoding.js','dist/esm/google/varint.js']){
        const source=await readFile(join(directory,file),'utf8');const header=source.match(/^(?:\/\/[^\n]*(?:\n|$))+/)?.[0];
        if(!header)throw new Error(`Missing upstream legal header: ${manifest.name}/${file}`);
        files.push({path:`${file} (legal header only)`,text:header.replace(/^\/\/ ?/gm,'').trim()});
      }
    }
    if(!files.length)missing.push(`${manifest.name}@${manifest.version}`);
    packages.push({name:manifest.name,version:manifest.version,license:manifest.license,files});
  }
  const peers=Object.fromEntries(Object.entries(manifest.peerDependencies??{}).filter(([name])=>!manifest.peerDependenciesMeta?.[name]?.optional));
  const dependencies={...manifest.dependencies,...manifest.optionalDependencies,...peers};
  for(const name of Object.keys(dependencies).sort()){
    const dependency=await installed(name,directory);
    if(dependency)await collect(dependency);
    else if(Object.hasOwn(manifest.dependencies??{},name)&&!Object.hasOwn(manifest.optionalDependencies??{},name))throw new Error(`Required dependency ${name} of ${manifest.name} is not installed; run npm ci.`);
  }
}
await collect(join(root,'apps/web'));
if(missing.length)throw new Error(`Installed packages without a complete notice file: ${missing.join(', ')}`);
packages.sort((a,b)=>a.name.localeCompare(b.name)||a.version.localeCompare(b.version));
const sections=['THIRD-PARTY SOFTWARE NOTICES\n\nGenerated from the installed @wangxu/web runtime dependency graph, including transitive dependencies and required installed peers. Optional peers that are direct runtime dependencies are included through those direct dependencies.\nRegenerate: node scripts/generate-notices.mjs\n\nKayKit models retain their original CC0 notices in /assets/characters/LICENSE.txt and /assets/dungeon/LICENSE.txt. Their file provenance is recorded in /assets/manifest.json.'];
for(const package_ of packages){
  sections.push(`${'='.repeat(78)}\n${package_.name}@${package_.version}${typeof package_.license==='string'?` (${package_.license})`:''}\n${'='.repeat(78)}`);
  for(const notice of package_.files)sections.push(`${package_.name}/${notice.path}\n${'-'.repeat(78)}\n${notice.text}`);
}
const text=`${sections.join('\n\n')}\n`;
if(process.argv.includes('--check')){
  if(await readFile(destination,'utf8')!==text)throw new Error('THIRD_PARTY_NOTICES.txt is out of date.');
}else await writeFile(destination,text);
console.log(JSON.stringify({output:'apps/web/public/THIRD_PARTY_NOTICES.txt',packages:packages.length,noticeFiles:packages.reduce((n,p)=>n+p.files.length,0),bytes:Buffer.byteLength(text),checked:process.argv.includes('--check')}));
